  'PrecioPagos': 'NuevaPlanta:2026-01:PrecioPagos',
  'AlcanceTrabajo': 'NuevaPlanta:2026-01:AlcanceTrabajo',
  'Responsabilidades': 'NuevaPlanta:2026-01:Responsabilidades',
