  'TerminacionRescision': 'NuevaPlanta:2026-01:TerminacionRescision',
  'OtroDesconocido': 'NuevaPlanta:2026-01:OtroDesconocido'
};

return [{ json: { 
  ...prevData, 
  routerOutput,
  rule_id: ruleIdMap[routerOutput.route] || 'NuevaPlanta:2026-01:OtroDesconocido'
}}];

// Si no hay regla en DB, usar configuración por defecto
