  // Default policy for Nueva Planta
  policySpec = {
    rule_id: prevData.rule_id,
    clause_family: prevData.routerOutput.route,
    required: true,
    analysis_mode: 'MODE_ENUMERATED_DEVIATIONS',
    standard_position: {
      text: 'Posición estándar no definida para esta familia.',
      summary: 'Revisar manualmente'
