const prevData = $('Parse Paranoid').first().json;
let valuatorOutput = { 
  decision: 'ACCEPT', 
  final_status: 'Compliant',
  needs_review: false, 
  proposed_changes: [], 
  internal_comment: '',
  client_state: 'OK',
  confidences: { anchor_confidence: 0.5 }
};

try {
  const response = $json;
  const content = response.choices?.[0]?.message?.content || '{}';
  valuatorOutput = JSON.parse(content);
} catch (e) {
  console.log('Valuator parse error:', e.message);
}

return [{ json: { ...prevData, valuatorOutput } }];

const data = $('Parse Valuator').first().json;
const valOut = data.valuatorOutput;
const policy = data.policySpec;

// Determinar decisión final basada en matriz de gating
let decision = 'ESCALATE_HUMAN';
let escalation = { recommended: false, block_export: false, reason: '' };

const finalStatus = valOut.final_status;
const analysisMode = policy.analysis_mode;
const required = policy.required;
const anchorConf = valOut.confidences?.anchor_confidence || 0;

if (finalStatus === 'Compliant') {
    decision = 'AUTO_PASS';
    escalation = { recommended: false, block_export: false, reason: '' };
} else if (finalStatus === 'AcceptableDeviation') {
    if (analysisMode === 'MODE_STRICT_NO_DEVIATIONS') {
        decision = 'ESCALATE_HUMAN';
        escalation = { recommended: true, block_export: policy.routing_policy?.block_export_if_escalated, reason: 'STRICT_MODE_DEVIATION' };
    } else {
        decision = 'AUTO_PASS';
        escalation = { recommended: false, block_export: false, reason: '' };
    }
} else if (finalStatus === 'UnacceptableDeviation') {
    if (required) {
        decision = 'BLOCK_EXPORT';
        escalation = { recommended: true, block_export: true, reason: 'REQUIRED_CLAUSE_VIOLATION' };
    } else {
        decision = 'AUTO_REDLINEDRAFT';
        escalation = { recommended: false, block_export: false, reason: '' };
    }
} else if (finalStatus === 'Ambiguous' || anchorConf < 0.7) {
    decision = 'ESCALATE_HUMAN';
    escalation = { recommended: true, block_export: policy.routing_policy?.block_export_if_escalated, reason: 'AMBIGUOUS_OR_LOW_CONFIDENCE' };
}

// Map to client_state for frontend
let client_state = 'NEEDS_REVIEW';
if (decision === 'AUTO_PASS') client_state = 'OK';
else if (decision === 'AUTO_REDLINEDRAFT') client_state = 'RECOMMENDED';
else if (decision === 'ESCALATE_HUMAN') client_state = 'REQUIRED';
else if (decision === 'BLOCK_EXPORT') client_state = 'BLOCKED';

// Override with valuator's client_state if provided
if (valOut.client_state) {
  client_state = valOut.client_state;
}

return [{ json: { 
  ...data, 
  decisorOutput: { decision, escalation, client_state } 
}}];

